// Parses the CoachMatch "cancellation CONFIRMED" email.
// NOT the "cancellation request" one -- see the filter for why they are easy to confuse.
//
// Real body (whitespace-flattened):
//   "Coach Match Cancellation Confirmation ... This is a confirmation that
//    Nelson Carrion () has cancelled their Coach Match Bronze level coaching
//    service subscription."
//
// Note the EMPTY parentheses. TrainingPeaks does not include the athlete's email
// on this template -- it does on the "request" one, but not here. So this branch
// cannot join on email like every other branch in this workflow does.

return $input.all().map(item => {
  const flat = (item.json.textPlain || '').replace(/\s+/g, ' ').trim();
  const subject = item.json.subject || '';

  const m = flat.match(
    /confirmation that\s+(.+?)\s*\(([^)]*)\)\s+has cancelled their Coach Match\s+(\w+)\s+level/i
  );

  // The athlete's name appears in the subject too. Two independent sources for the
  // one field everything downstream depends on, so a template change shows up as a
  // mismatch instead of a silent wrong match.
  const s = subject.match(/Cancellation\s*-\s*Athlete\s+(.+)$/i);

  const nameFromBody = m ? m[1].trim() : '';
  const nameFromSubject = s ? s[1].trim() : '';

  return { json: {
    parse_ok: Boolean(m || s),
    athlete_name: nameFromBody || nameFromSubject,
    name_from_body: nameFromBody,
    name_from_subject: nameFromSubject,
    name_mismatch: Boolean(nameFromBody && nameFromSubject &&
                           nameFromBody.toLowerCase() !== nameFromSubject.toLowerCase()),
    email_in_email: m ? m[2].trim() : '',   // expected empty; captured in case TP fixes it
    tier: m ? m[3] : '',
    cancelled_on: (item.json.date || '').slice(0, 10),
  }};
});

// Matches the cancelled athlete to a Twenty record BY NAME, because the CoachMatch
// cancellation email carries no email address.
//
// Strategy: fetch only 1:1 coaching athletes (a few dozen), then match in code.
// Twenty's API name filters are brittle against how a name was split on the way in --
// "Rafael A Giraldo R" could be stored several ways -- so the comparison is done here,
// on a normalized token set, where accents, case, punctuation and word order stop mattering.

function norm(s) {
  return String(s || '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')   // strip accents
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .split(/\s+/).filter(Boolean).sort().join(' ');
}

const wanted = norm($('Parse CoachMatch Cancellation').item.json.athlete_name);
const people = $json?.data?.people || [];

const scored = people.map(p => {
  const full = [p?.name?.firstName, p?.name?.lastName].filter(Boolean).join(' ');
  return { id: p.id, full, email: p?.emails?.primaryEmail || '',
           lang: p?.preferredLanguage || '', key: norm(full) };
});

let hits = scored.filter(p => p.key === wanted);

// Fallback: same surname set, one name written more fully than the other
// ("Nelson Carrion" vs "Nelson Andres Carrion"). Only used when the exact pass finds
// nothing, and still requires a unique winner.
if (hits.length === 0) {
  const wt = wanted.split(' ');
  hits = scored.filter(p => {
    const pt = p.key.split(' ');
    const shared = wt.filter(t => pt.includes(t));
    return shared.length >= 2 && (shared.length === wt.length || shared.length === pt.length);
  });
}

return [{ json: {
  match_count: hits.length,
  candidates_searched: scored.length,
  person_id: hits.length === 1 ? hits[0].id : '',
  email: hits.length === 1 ? hits[0].email : '',
  full_name: hits.length === 1 ? hits[0].full : $('Parse CoachMatch Cancellation').item.json.athlete_name,
  preferredLanguage: hits.length === 1 ? (hits[0].lang || 'UNKNOWN') : 'UNKNOWN',
  near_misses: hits.length > 1 ? hits.map(h => h.full + ' <' + h.email + '>').join(' | ') : '',
}}];

